mapper.select:
SELECT d.internal_class, d.internal_method, d.mcp_tool_enabled,d.portal_visible, d.id, d.service, d.version, d.method, d.name, COALESCE(c.name,d.category) AS category, d.owner, COALESCE(p.display_name,d.owner) AS owner_name, d.protocol, CASE WHEN p.id IS NOT NULL THEN true ELSE false END AS owner_profile_linked, p.employee_no AS owner_employee_no, p.tenant_id AS owner_tenant_id, p.tenant_name AS owner_tenant_name, d.draft_revision, r.draft_revision AS live_draft_revision, d.definition_json, r.snapshot_json AS live_snapshot_json, COALESCE(s.enabled, false) AS enabled, s.pending_release_id, AS latest_review_status, latest.draft_revision AS latest_review_draft_revision, current_revision.recorded_at AS updated_at FROM catalog_api_draft d LEFT JOIN catalog_category_alias ca ON ca.category_key=d.category LEFT JOIN catalog_category c ON c.id=ca.category_id LEFT JOIN access_employee_profile p ON p.id=d.owner LEFT JOIN publication_state s ON s.api_id = d.id LEFT JOIN publication_release r ON r.id = s.live_release_id LEFT JOIN catalog_api_revision current_revision ON current_revision.api_id = d.id AND current_revision.revision = d.draft_revision LEFT JOIN publication_release latest ON latest.id = ( SELECT recent.id FROM publication_release recent WHERE recent.api_id = d.id ORDER BY recent.submitted_at DESC, recent.id DESC LIMIT 1 ) WHERE d.environment_id=#{environmentId} AND (d.service LIKE #{pattern} ESCAPE '!' OR d.method LIKE #{pattern} ESCAPE '!' OR d.name LIKE #{pattern} ESCAPE '!' OR CONCAT(d.service, '.', d.method) LIKE #{pattern} ESCAPE '!') AND COALESCE(c.id,d.category) = COALESCE((SELECT category_id FROM catalog_category_alias WHERE category_key=#{filter.category}),#{filter.category})
AND d.protocol IN #{value}
AND (CASE WHEN s.live_release_id IS NULL THEN 'UNPUBLISHED' ELSE 'PUBLISHED' END) IN #{value}
AND () IN #{value}
AND (CASE WHEN COALESCE(s.enabled, false) THEN 'ENABLED' ELSE 'DISABLED' END) IN #{value}
AND (CASE WHEN d.mcp_tool_enabled THEN 'ENABLED' ELSE 'DISABLED' END) IN #{value}
AND (d.internal_class=#{filter.internalClass} OR d.internal_class LIKE #{simplePattern} ESCAPE '!' OR d.internal_class LIKE CONCAT('%$',SUBSTRING(#{simplePattern},3)) ESCAPE '!') AND d.internal_class LIKE #{classPattern} ESCAPE '!'
AND d.internal_method=#{filter.internalMethod}AND d.internal_method LIKE #{methodPattern} ESCAPE '!' AND p.id=#{filter.ownerId}
ORDER BY (current_revision.recorded_at IS NULL), current_revision.recorded_at DESC, d.id DESC ORDER BY (current_revision.recorded_at IS NULL), current_revision.recorded_at, d.id ORDER BY d.name, d.id ORDER BY d.name DESC, d.id DESC ORDER BY d.service, d.version, d.method, d.id

SELECT * FROM catalog_api_draft WHERE environment_id=#{environmentId} AND (

    (service=#{op.service} AND version=#{op.version} AND method=#{op.method})
)

SELECT service, version, method FROM catalog_api_draft
WHERE environment_id=#{environmentId} AND CONCAT(service,'_',method,'_',REPLACE(REPLACE(version,'.','_'),'-','_')) IN
#{toolName}
ORDER BY service, method, version
LIMIT #{limit}

SELECT * FROM catalog_api_draft WHERE environment_id=#{environmentId} AND id IN
#{id}
ORDER BY id FOR UPDATE
